begin transaction read only;
select jsonb_build_object('policies',(select jsonb_agg(to_jsonb(p) order by tablename) from pg_policies p where schemaname='public' and policyname='wellness_consent_gate'),'function',(select jsonb_build_object('definition',pg_get_functiondef(p.oid),'anon_execute',has_function_privilege('anon',p.oid,'execute'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'execute')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='evolve_wellness_allowed'),'rls',(select jsonb_agg(jsonb_build_object('table',relname,'enabled',relrowsecurity) order by relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and relname in ('evolve_client_profiles','evolve_client_habits','evolve_client_planner','evolve_client_workouts','evolve_client_meals','evolve_client_measurements','evolve_client_lifestyle'))) as verification;
rollback;